		s    llm.DispatchStat
	}
	rows := make([]row, 0, len(st.Kinds))
	var sum time.Duration
	var count int
	for k, v := range st.Kinds {
		rows = append(rows, row{k, v})
		sum += v.GPU
		count += v.Count
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].s.GPU > rows[j].s.GPU })
	fmt.Printf("\n  dispatches by label — %d a step over %d labels, %.3f ms of the %.3f the command buffer took\n",
		count/max(tokens, 1), len(rows), ms(sum), ms(st.GPU))
	fmt.Printf("    %-24s %8s %8s %9s %7s\n", "label", "n/step", "ms/step", "us each", "share")
	for _, r := range rows {
