package llm

import (
	"fmt"
	"math/rand"
	"os"
	"strconv"
	"strings"
	"testing"
	"time"
)

// faults reads the process's minor and major fault counters.
func faults(t *testing.T) (min, maj uint64) {
	b, err := os.ReadFile("/proc/self/stat")
	if err != nil {
		t.Fatal(err)
	}
	// Fields after the comm field, which may contain spaces.
	f := strings.Fields(b[strings.LastIndex(string(b), ") ")+2:])
	_ = f
	g := strings.Fields(string(b)[strings.LastIndex(string(b), ") ")+2:])
	min, _ = strconv.ParseUint(g[7], 10, 64)  // minflt is field 10 -> index 7 after state
	maj, _ = strconv.ParseUint(g[9], 10, 64)  // majflt is field 12 -> index 9
	return
}

func TestPLEGatherCost(t *testing.T) {
	m, err := Open(os.Getenv("M"))
	if err != nil {
		t.Skip(err)
	}
	defer m.Close()
	c, ok, err := m.PLEConfigFor()
	if err != nil || !ok {
		t.Fatalf("ple config: %v %v", ok, err)
	}
	tt, err := m.Set.Get("per_layer_token_embd.weight")
	if err != nil {
		t.Fatal(err)
	}
	nrow := tt.Dims[1]
	t.Logf("table %d rows x %d, heads %d", nrow, c.HeadDim, c.NHeads)

	rng := rand.New(rand.NewSource(1))
	const steps = 200
	rows := make([]int32, c.NHeads)
	run := func(name string, pick func(i int) int32) {
		mi0, ma0 := faults(t)
		t0 := time.Now()
		for s := 0; s < steps; s++ {
			for h := range rows {
				rows[h] = pick(h)
			}
			if _, err := m.PLEGather(rows, c.NHeads, c.HeadDim); err != nil {
				t.Fatal(err)
			}
		}
		d := time.Since(t0)
		mi1, ma1 := faults(t)
		fmt.Printf("%-10s %7.1f us a step, minflt %5d majflt %5d over %d steps\n",
			name, float64(d.Microseconds())/steps, mi1-mi0, ma1-ma0, steps)
	}
	run("cold", func(int) int32 { return int32(rng.Int63n(nrow)) })
	run("cold2", func(int) int32 { return int32(rng.Int63n(nrow)) })
	fixed := make([]int32, c.NHeads)
	for h := range fixed {
		fixed[h] = int32(rng.Int63n(nrow))
	}
	run("hot", func(i int) int32 { return fixed[i] })
}
