package llm

import (
	"fmt"
	"math/rand"
	"os"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

func faults(t *testing.T) (min, maj uint64) {
	b, err := os.ReadFile("/proc/self/stat")
	if err != nil {
		t.Fatal(err)
	}
	g := strings.Fields(string(b)[strings.LastIndex(string(b), ") ")+2:])
	min, _ = strconv.ParseUint(g[7], 10, 64)
	maj, _ = strconv.ParseUint(g[9], 10, 64)
	return
}

var sink byte

// TestPLEGatherCost prices the n-gram gather against the thing it actually
// costs. Each arm draws fresh rows out of a 320-million-row table, so no arm
// can be warmed by the one before it.
func TestPLEGatherCost(t *testing.T) {
	m, err := Open(os.Getenv("M"))
	if err != nil {
		t.Skip(err)
	}
	defer m.Close()
	c, ok, err := m.PLEConfig()
	if err != nil || !ok {
		t.Fatalf("ple config: %v %v", ok, err)
	}
	tt, err := m.Set.Get("per_layer_token_embd.weight")
	if err != nil {
		t.Fatal(err)
	}
	nrow := tt.Dims[1]
	t.Logf("table %d rows x %d, %d heads a token", nrow, c.HeadDim, c.NHeads)

	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	const steps = 200
	rows := make([]int32, c.NHeads)
	arm := func(name string, prefetch bool) {
		mi0, ma0 := faults(t)
		t0 := time.Now()
		for s := 0; s < steps; s++ {
			for h := range rows {
				rows[h] = int32(rng.Int63n(nrow))
			}
			if prefetch {
				var wg sync.WaitGroup
				for _, r := range rows {
					wg.Add(1)
					go func(r int32) {
						defer wg.Done()
						row := tt.Row(int64(r))
						sink += row[0] + row[len(row)-1]
					}(r)
				}
				wg.Wait()
			}
			if _, err := m.PLEGather(rows, c.NHeads, c.HeadDim); err != nil {
				t.Fatal(err)
			}
		}
		d := time.Since(t0)
		mi1, ma1 := faults(t)
		fmt.Printf("%-10s %7.1f us a step, minflt %5.1f majflt %5.2f a step\n",
			name, float64(d.Microseconds())/steps,
			float64(mi1-mi0)/steps, float64(ma1-ma0)/steps)
	}
	arm("serial", false)
	arm("parallel", true)
	arm("serial", false)
	arm("parallel", true)
}
EOF
