func TestPLEGatherPoolIsTheSerialGather(t *testing.T) {
	m, _, c, ids := pleFixtures(t)
	all := PLERows(c, ids)
	for _, n := range []int{1, 2, 15, 16, 17, 31, 33, len(all)} {
